  /** Money still owed on one boat across its held and confirmed bookings; overpayments count as 0. */
  outstanding(boatId: string): Pence {
    let total: Pence = 0;
    for (const b of this.bookings) {
      if (b.boatId !== boatId) continue;
      if (b.state !== "held" && b.state !== "confirmed") continue;
      total += Math.max(0, b.chargePence - b.paidPence);
    }
    return total;
